-- Read-only block-extrema follow-up derived from existing seasonal masked-block query.
-- Read-only quarterly score. Execute this SELECT independently.
WITH sizes AS (SELECT 3600 block_s,'1h' block_type,12 expected_slots UNION ALL SELECT 21600,'6h',72 UNION ALL SELECT 86400,'24h',288), candidates AS (SELECT s.block_s,s.block_type,s.expected_slots,FLOOR((a.dateTime-1577836800)/s.block_s)*s.block_s+1577836800 block_start,COUNT(*) target_n,MIN(a.dateTime) first_t,MAX(a.dateTime) last_t FROM sizes s JOIN loucka_reconstruction.archive a ON a.dateTime>=1577836800 AND a.dateTime<1585699200 AND a.outTemp IS NOT NULL AND a.interval=5 AND NOT EXISTS (SELECT 1 FROM loucka_reconstruction.reconstruction_changes c WHERE c.target_time=a.dateTime AND c.variable='outTemp') GROUP BY s.block_s,s.block_type,s.expected_slots,block_start HAVING target_n=s.expected_slots AND first_t=block_start AND last_t=block_start+s.block_s-300 AND block_start+s.block_s<1585699200), blocks AS (SELECT c.*,l.outTemp left_y,r.outTemp right_y FROM candidates c JOIN loucka_reconstruction.archive l ON l.dateTime=c.block_start-300 AND l.outTemp IS NOT NULL AND l.interval=5 AND NOT EXISTS (SELECT 1 FROM loucka_reconstruction.reconstruction_changes x WHERE x.target_time=l.dateTime AND x.variable='outTemp') JOIN loucka_reconstruction.archive r ON r.dateTime=c.block_start+c.block_s AND r.outTemp IS NOT NULL AND r.interval=5 AND NOT EXISTS (SELECT 1 FROM loucka_reconstruction.reconstruction_changes x WHERE x.target_time=r.dateTime AND x.variable='outTemp')), scores AS (SELECT b.block_type,b.block_start,t.dateTime,t.outTemp y,b.left_y+(b.right_y-b.left_y)*(t.dateTime-(b.block_start-300))/(b.block_s+300) interp,r.temperature_c ref,CASE WHEN r.temperature_c IS NOT NULL AND r.source_resolution='5min' AND r.quality_status='reference_only' THEN 1 ELSE 0 END ref_ok,CASE WHEN r.temperature_c=0 AND t.outTemp>=20 THEN 1 ELSE 0 END zero_hot,(0.7886750170162296+0.9352562666974354*r.temperature_c+-0.20129399741209056*SIN(2*PI()*MOD(t.dateTime,86400)/86400)+-0.09305546547425936*COS(2*PI()*MOD(t.dateTime,86400)/86400)+-0.3075224035244028*SIN(2*PI()*(CASE WHEN t.dateTime<1577836800 THEN t.dateTime-1546300800 ELSE t.dateTime-1577836800 END)/(CASE WHEN t.dateTime>=1577836800 THEN 31622400 ELSE 31536000 END))+-1.496803043901965*COS(2*PI()*(CASE WHEN t.dateTime<1577836800 THEN t.dateTime-1546300800 ELSE t.dateTime-1577836800 END)/(CASE WHEN t.dateTime>=1577836800 THEN 31622400 ELSE 31536000 END))) ols FROM blocks b JOIN loucka_reconstruction.archive t ON t.dateTime>=b.block_start AND t.dateTime<b.block_start+b.block_s AND t.outTemp IS NOT NULL AND t.interval=5 AND NOT EXISTS (SELECT 1 FROM loucka_reconstruction.reconstruction_changes x WHERE x.target_time=t.dateTime AND x.variable='outTemp') LEFT JOIN loucka_reconstruction.reference_observations r ON r.station_id='luhamet_sehradice' AND r.observed_at_utc=t.dateTime)
, extrema AS (SELECT block_type,block_start,COUNT(*) target_n,SUM(ref_ok) ref_n,SUM(zero_hot) flag_n,MAX(y) actual_max,MIN(y) actual_min,MAX(interp) interp_max,MIN(interp) interp_min,MAX(CASE WHEN ref_ok=1 THEN ref END) direct_max,MIN(CASE WHEN ref_ok=1 THEN ref END) direct_min,MAX(CASE WHEN ref_ok=1 THEN ols END) ols_max,MIN(CASE WHEN ref_ok=1 THEN ols END) ols_min FROM scores GROUP BY block_type,block_start), block_errors AS (SELECT *,CASE WHEN ref_n=target_n AND flag_n=0 THEN 1 ELSE 0 END clean,interp_max-actual_max imax_err,interp_min-actual_min imin_err,direct_max-actual_max dmax_err,direct_min-actual_min dmin_err,ols_max-actual_max omax_err,ols_min-actual_min omin_err FROM extrema) SELECT '2020Q1' period,block_type,COUNT(*) complete_blocks,SUM(target_n) masked_targets,SUM(clean) clean_reference_blocks,SUM(CASE WHEN flag_n>0 THEN 1 ELSE 0 END) flagged_blocks,SUM(ABS(imax_err)) interp_max_abs_all,SUM(POW(imax_err,2)) interp_max_sq_all,SUM(imax_err) interp_max_bias_all,MAX(ABS(imax_err)) interp_max_worst_all,SUM(ABS(imin_err)) interp_min_abs_all,SUM(POW(imin_err,2)) interp_min_sq_all,SUM(imin_err) interp_min_bias_all,MAX(ABS(imin_err)) interp_min_worst_all,SUM(CASE WHEN clean=1 THEN ABS(imax_err) ELSE 0 END) interp_max_abs_clean,SUM(CASE WHEN clean=1 THEN POW(imax_err,2) ELSE 0 END) interp_max_sq_clean,SUM(CASE WHEN clean=1 THEN imax_err ELSE 0 END) interp_max_bias_clean,SUM(CASE WHEN clean=1 THEN ABS(imin_err) ELSE 0 END) interp_min_abs_clean,SUM(CASE WHEN clean=1 THEN POW(imin_err,2) ELSE 0 END) interp_min_sq_clean,SUM(CASE WHEN clean=1 THEN imin_err ELSE 0 END) interp_min_bias_clean,SUM(CASE WHEN clean=1 THEN ABS(dmax_err) ELSE 0 END) direct_max_abs_clean,SUM(CASE WHEN clean=1 THEN POW(dmax_err,2) ELSE 0 END) direct_max_sq_clean,SUM(CASE WHEN clean=1 THEN dmax_err ELSE 0 END) direct_max_bias_clean,SUM(CASE WHEN clean=1 THEN ABS(dmin_err) ELSE 0 END) direct_min_abs_clean,SUM(CASE WHEN clean=1 THEN POW(dmin_err,2) ELSE 0 END) direct_min_sq_clean,SUM(CASE WHEN clean=1 THEN dmin_err ELSE 0 END) direct_min_bias_clean,SUM(CASE WHEN clean=1 THEN ABS(omax_err) ELSE 0 END) ols_max_abs_clean,SUM(CASE WHEN clean=1 THEN POW(omax_err,2) ELSE 0 END) ols_max_sq_clean,SUM(CASE WHEN clean=1 THEN omax_err ELSE 0 END) ols_max_bias_clean,SUM(CASE WHEN clean=1 THEN ABS(omin_err) ELSE 0 END) ols_min_abs_clean,SUM(CASE WHEN clean=1 THEN POW(omin_err,2) ELSE 0 END) ols_min_sq_clean,SUM(CASE WHEN clean=1 THEN omin_err ELSE 0 END) ols_min_bias_clean FROM block_errors GROUP BY block_type ORDER BY block_type;
